window.docContents[174].resolve({"/UD-III___-storage-and-commands/Expression-statement/#Core-C_________-natural-semantics--UD-III___-storage-and-commands--Expression-statement":{"contents":"An expression followed by ; is a command that evaluates the expression and discards the value. Any type is accepted, void included, which allows a call to a void function as a statement.\n\n","context":"Core C++, natural semantics\u0009UD III, storage and commands","header":"3.6. Expression statement","id":"/UD-III___-storage-and-commands/Expression-statement/#Core-C_________-natural-semantics--UD-III___-storage-and-commands--Expression-statement"}});